local _, namespace = ...
local Tooltips = {}
local TEXT = {
    ["Language"] = { "UI language for this character. Automatic follows the WoW client; unsupported languages use English. Updates immediately without changing spell-tooltip parsing.", "UI-Sprache dieses Charakters. Automatisch folgt dem WoW-Client; nicht unterstützte Sprachen nutzen Englisch. Wirkt sofort und ändert keine Zauberauswertung." },
    ["option:Language:auto"] = { "Follow the WoW client language. Use English when no UI translation is available.", "Folgt der WoW-Clientsprache. Fehlt eine UI-Übersetzung, wird Englisch verwendet." },
    ["option:Language:deDE"] = { "Use German for the addon UI and help. Keep the actual client language for spell data.", "Verwendet Deutsch für Addon-Oberfläche und Hilfe. Zauberdaten nutzen weiterhin die tatsächliche Clientsprache." },
    ["option:Language:enUS"] = { "Use English for the addon UI and help. Keep the actual client language for spell data.", "Verwendet Englisch für Addon-Oberfläche und Hilfe. Zauberdaten nutzen weiterhin die tatsächliche Clientsprache." },
    ["option:Language:frFR"] = { "Use French for the addon UI and help. Spell data still use the client language.", "Verwendet Französisch für Oberfläche und Hilfe. Zauberdaten nutzen weiterhin die Clientsprache." },
    ["option:Language:esES"] = { "Use Spanish for the addon UI and help. Spell data still use the client language.", "Verwendet Spanisch für Oberfläche und Hilfe. Zauberdaten nutzen weiterhin die Clientsprache." },
    ["Show on nameplates"] = { "Show forecasts on enemy nameplates. Tracking and the target display stay independent.", "Zeigt Prognosen auf Gegner-Namensplaketten. Tracking und Zielanzeige bleiben unabhängig." },
    ["Show on target frame"] = { "Show the forecast and enabled kill icon on your enemy target frame.", "Zeigt Prognose und aktiviertes Kill-Symbol am Zielfenster des Gegners." },
    ["Minimap button"] = { "Show the minimap settings button. /dot still works when hidden.", "Zeigt den Einstellungsbutton an der Minimap. Ausgeblendet bleibt /dot verfügbar." },
    ["Link appearance"] = { "Link colours, fill, outline and icon design. Icon size/position, effects and visibility stay separate.", "Koppelt Farben, Füllung, Kontur und Icon-Design. Icon-Größe/-Position, Effekte und Sichtbarkeit bleiben getrennt." },
    ["Show damage bar"] = { "Show the DoT fill, outline and bar effects. Kill icon and damage text have separate switches.", "Zeigt DoT-Fläche, Kontur und Balkeneffekte. Kill-Symbol und Schadenstext haben eigene Schalter." },
    ["Color mode"] = { "Use one fill colour, fixed school colours or a separate colour for each DoT.", "Verwendet eine Füllfarbe, feste Farben je Schadensschule oder eine eigene Farbe je DoT." },
    ["Fill texture"] = { "Choose the damage-bar pattern. None hides only the fill, not the outline or kill icon.", "Wählt das Muster des Schadensbalkens. „Keine“ blendet nur die Füllung aus, nicht Kontur oder Kill-Symbol." },
    ["Fill tint"] = { "Colour used with One color. School and per-DoT modes use their own colours.", "Füllfarbe im Modus „Einfarbig (Füllfarbe)“. Andere Farbmodi verwenden eigene Farben." },
    ["Fill opacity"] = { "Opacity of the bar fill: 0% invisible, 100% opaque. Outline and icon are separate.", "Deckkraft der Füllung: 0 % unsichtbar, 100 % deckend. Kontur und Icon sind unabhängig." },
    ["Outline"] = { "Choose a solid, dashed or hidden border around the forecast.", "Wählt eine durchgehende, gestrichelte oder ausgeblendete Kontur um die Prognose." },
    ["Outline tint"] = { "Colour of the outline and its optional glow.", "Farbe der Kontur und ihres optionalen Leuchtens." },
    ["Dash pattern"] = { "Length of each dash in a dashed outline. Does not affect the stripe fill.", "Länge der Striche einer gestrichelten Kontur. Ändert nicht das Streifenmuster der Füllung." },
    ["Outline width"] = { "Thickness of the forecast border in pixels.", "Dicke der Kontur um die Prognose in Pixeln." },
    ["Outline opacity"] = { "Opacity of the border; also controls the strength of its optional glow.", "Deckkraft der Kontur; beeinflusst auch die Stärke ihres optionalen Leuchtens." },
    ["Outline glow"] = { "Add a soft glow in the outline colour. Turn off to keep only the thin border.", "Ergänzt weiches Leuchten in Konturfarbe. Ausgeschaltet bleibt die dünne Kontur erhalten." },
    ["Glow size"] = { "Width of the soft glow outside the outline, in pixels.", "Breite des weichen Leuchtens außerhalb der Kontur in Pixeln." },
    ["DoT colour"] = { "Colour for this DoT across all ranks. Automatic uses its default colour.", "Farbe für diesen DoT über alle Ränge. „Automatisch“ verwendet seine Standardfarbe." },
    ["Automatic"] = { "Reset all per-DoT colours for this display. Linked colours also update the other display.", "Setzt alle DoT-Farben dieser Anzeige zurück. Bei gekoppelten Farben wird auch die andere Anzeige angepasst." },
    ["Show kill icon"] = { "Show the icon when conservative remaining DoT damage covers current HP. It can appear later than the bar.", "Zeigt das Icon, wenn vorsichtig geschätzter DoT-Restschaden die HP abdeckt. Es kann später als der Balken erscheinen." },
    ["Icon design"] = { "Choose the kill symbol. Does not change when a target is considered lethal.", "Wählt das Kill-Symbol. Die Schwelle für die Kill-Prognose bleibt gleich." },
    ["X color"] = { "Set the X colour for this display. It stays saved when you choose another icon.", "Wählt die X-Farbe für diese Anzeige. Beim Symbolwechsel bleibt sie gespeichert." },
    ["Diamond color"] = { "Set the diamond colour for this display. It stays saved when you choose another icon.", "Wählt die Rautenfarbe für diese Anzeige. Beim Symbolwechsel bleibt sie gespeichert." },
    ["Position"] = { "Place the nameplate kill icon left, right or above the health bar.", "Platziert das Kill-Symbol links, rechts oder oberhalb des Lebensbalkens der Namensplakette." },
    ["Anchor in use"] = { "The target icon's current anchor. Auto uses the visible portrait, otherwise the health bar.", "Aktueller Anker des Symbols im Zielfenster. Automatisch nutzt das sichtbare Porträt, sonst den Lebensbalken." },
    ["Icon anchor"] = { "Custom target-icon anchor. Empty uses the portrait automatically. Enter or leaving applies; Escape cancels.", "Eigener Symbolanker im Zielfenster. Leer nutzt automatisch das Porträt. Enter oder Verlassen übernimmt, Escape verwirft." },
    ["Use portrait"] = { "Clear the custom anchor and use the visible portrait, otherwise the health bar. Keep icon offsets.", "Entfernt den eigenen Anker und nutzt das sichtbare Porträt, sonst den Lebensbalken. Icon-Abstände bleiben erhalten." },
    ["Size"] = { "Width and height of the kill icon in pixels.", "Breite und Höhe des Kill-Symbols in Pixeln." },
    ["Horizontal offset"] = { "Move the kill icon from its anchor: negative left, positive right.", "Verschiebt das Kill-Symbol relativ zum Anker: negativ nach links, positiv nach rechts." },
    ["Vertical offset"] = { "Move the kill icon from its anchor: negative down, positive up.", "Verschiebt das Kill-Symbol relativ zum Anker: negativ nach unten, positiv nach oben." },
    ["Pulse icon"] = { "Pulse the visible target kill icon's opacity. Does not change its size or kill threshold.", "Lässt die Deckkraft des sichtbaren Kill-Symbols im Zielfenster pulsieren. Größe und Kill-Schwelle bleiben gleich." },
    ["Replay effects"] = { "Restart enabled preview effects at the current HP and DoT values. Pause running preview ticks.", "Startet aktive Vorschau-Effekte bei unveränderten HP-/DoT-Werten neu. Laufende Vorschau-Ticks werden pausiert." },
    ["Smooth bar changes"] = { "Smooth growing bars. Reduced remaining damage is shown immediately.", "Glättet wachsende Balken. Weniger Restschaden wird sofort angezeigt." },
    ["Flash on new DoT"] = { "Brief flash when a new or refreshed DoT appears in the display.", "Kurzer Blitz, wenn ein neuer oder erneuerter DoT in der Anzeige erscheint." },
    ["Segment dividers"] = { "Draw separators between individual DoT segments. Not used with One color.", "Zeichnet Trennlinien zwischen einzelnen DoT-Abschnitten. Entfällt im Modus „Einfarbig (Füllfarbe)“." },
    ["More visual effects"] = { "Show extra effect controls. This switch alone does not enable or disable effects.", "Öffnet zusätzliche Effektoptionen. Dieser Schalter allein aktiviert oder deaktiviert keine Effekte." },
    ["Edge spark"] = { "Add a bright spark at the right edge of the outlined forecast.", "Zeigt einen hellen Lichtsaum am rechten Rand der umrandeten Prognose." },
    ["Pulse outline"] = { "Gently pulse the outline's opacity.", "Lässt die Deckkraft der Kontur sanft pulsieren." },
    ["Shine sweep"] = { "Sweep a light across the target forecast at regular intervals.", "Lässt regelmäßig einen Lichtstreifen über die Prognose im Zielfenster wandern." },
    ["Shine interval"] = { "Seconds between light sweeps. Higher values mean less frequent sweeps.", "Sekunden zwischen Lichtdurchläufen. Höhere Werte bedeuten seltenere Durchläufe." },
    ["Animate stripes"] = { "Move either diagonal stripe fill on the target frame. Nameplate stripes stay static.", "Bewegt die diagonale Streifenfüllung im Zielfenster. Streifen auf Namensplaketten bleiben statisch." },
    ["Stripe speed"] = { "Stripe speed: 1x = default speed, 0.25x = quarter speed, 3x = triple speed. Other effects keep their speed.", "Streifentempo: 1x = Standardgeschwindigkeit, 0,25x = Vierteltempo, 3x = dreifaches Tempo. Andere Effekte bleiben gleich schnell." },
    ["Show damage text"] = { "Show rounded total remaining DoT damage on the target display.", "Zeigt den gerundeten gesamten DoT-Restschaden an der Zielanzeige." },
    ["Text position"] = { "Place the damage number left of, centred on or inside the right end of the bar.", "Platziert die Schadenszahl links neben, mittig auf oder rechts innerhalb des Balkens." },
    ["Text size"] = { "Font size of the target's remaining-damage number.", "Schriftgröße der Restschadenszahl im Zielfenster." },
    ["Text tint"] = { "Colour of the target's remaining-damage number.", "Farbe der Restschadenszahl im Zielfenster." },
    ["Tracking status"] = { "Shows whether tracking can read own DoTs or must estimate them. Some spells need a tick first.", "Zeigt, ob eigene DoTs lesbar sind oder geschätzt werden. Manche Zauber benötigen zuerst einen Tick." },
    ["Extra tick wait"] = { "Choose an extra first-tick wait. None never bypasses required aura/impact checks; the kill icon has its own safety margin.", "Wählt zusätzliches Warten auf den ersten Tick. „Keine“ überspringt keine nötige Aura-/Trefferprüfung; das Kill-Symbol nutzt einen Sicherheitsabzug." },
    ["Create report"] = { "Collect a support snapshot. /reload saves SavedVariables/DoTDamage.lua. Nothing is uploaded.", "Sammelt einen Diagnosebericht. /reload speichert SavedVariables/DoTDamage.lua. Es wird nichts hochgeladen." },
    ["Reset data"] = { "Clear this character's learned damage, not appearance or profiles. Click twice within 5 seconds.", "Löscht gelernte Schadenswerte dieses Charakters, nicht Optik oder Profile. Innerhalb von 5 Sekunden zweimal klicken." },
    ["Health bar path"] = { "Custom target health bar; must be a horizontal StatusBar. Empty uses auto detection. Enter or leaving applies; Escape cancels.", "Eigener Lebensbalken im Zielfenster; muss eine horizontale StatusBar sein. Leer nutzt automatische Erkennung. Enter oder Verlassen übernimmt, Escape verwirft." },
    ["Pick"] = { "Select a highlighted region outside combat. Left-click accepts; right-click cancels. A stable frame path is required.", "Wählt außerhalb des Kampfes ein markiertes Element. Linksklick übernimmt, Rechtsklick bricht ab. Ein stabiler Frame-Pfad ist nötig." },
    ["Health bar in use"] = { "Detected health-bar binding. An invalid custom path falls back to automatic detection.", "Erkannter Lebensbalken. Bei ungültigem eigenen Pfad wird automatische Erkennung verwendet." },
    ["Saved profiles"] = { "Load appearance and anchors for both displays. Keep local drafts per character; general switches and learned damage stay unchanged.", "Lädt Optik und Anker beider Anzeigen. Lokale Entwürfe je Charakter, allgemeine Schalter und Lernwerte bleiben erhalten." },
    ["Editing status"] = { "An asterisk means local unsaved edits. Presets are read-only; create your own profile to save changes.", "Ein Stern bedeutet ungespeicherte lokale Änderungen. Vorlagen sind schreibgeschützt; zum Speichern ein eigenes Profil erstellen." },
    ["Save changes"] = { "Overwrite the selected shared profile with both displays' current appearance. Only available for an edited own profile.", "Überschreibt das gewählte gemeinsame Profil mit der Optik beider Anzeigen. Nur bei geändertem eigenen Profil verfügbar." },
    ["New name"] = { "Unique name for Create as new or Rename. Does not rename a profile until you press that button.", "Eindeutiger Name für „Als neu speichern“ oder „Umbenennen“. Erst die jeweilige Schaltfläche übernimmt den Namen." },
    ["Create as new"] = { "Save both displays' current appearance as a new account-wide profile using New name.", "Speichert die aktuelle Optik beider Anzeigen unter „Neuer Name“ als neues accountweites Profil." },
    ["Rename"] = { "Rename the selected own profile using New name. Presets cannot be renamed.", "Benennt das gewählte eigene Profil mit „Neuer Name“ um. Vorlagen lassen sich nicht umbenennen." },
    ["Revert"] = { "Discard this character's edits to the selected own profile and reload its saved appearance. Click twice within 5 seconds.", "Verwirft lokale Änderungen am gewählten eigenen Profil und lädt dessen gespeicherte Optik. Zweimal innerhalb von 5 Sekunden klicken." },
    ["Delete"] = { "Delete the shared own profile; keep the current appearance. Click twice within 5 seconds. Presets cannot be deleted.", "Löscht das accountweite eigene Profil; aktuelle Optik bleibt erhalten. Zweimal innerhalb von 5 Sekunden klicken. Vorlagen sind geschützt." },
    ["Use context profiles"] = { "Automatically select this character's assigned profile when group or instance context changes. An assignment may apply immediately.", "Wählt bei Gruppen-/Instanzwechsel das zugewiesene Profil dieses Charakters. Eine Zuweisung kann sofort wirksam werden." },
    ["Solo"] = { "Profile for playing alone outside a dungeon or raid. Keep current profile means no switch.", "Profil für Solospiel außerhalb von Dungeon oder Raid. „Aktuelles Profil behalten“ bedeutet keinen Wechsel." },
    ["Group"] = { "Profile for a party outside a dungeon or raid. Dungeon and Raid assignments take precedence.", "Profil für Gruppen außerhalb von Dungeon oder Raid. Dungeon- und Raid-Zuweisungen haben Vorrang." },
    ["Dungeon"] = { "Profile inside a party dungeon, even when entering alone.", "Profil innerhalb einer Dungeon-Instanz, auch beim Betreten ohne Gruppe." },
    ["Raid"] = { "Profile in a raid group or raid instance, except a party dungeon uses Dungeon.", "Profil für Raid-Gruppe oder Raid-Instanz; eine Dungeon-Instanz verwendet die Dungeon-Zuweisung." },
    ["Current context"] = { "Currently detected Solo, Group, Dungeon or Raid context. Read-only.", "Aktuell erkannt: Solo, Gruppe, Dungeon oder Raid. Reine Anzeige." },
    ["Profile preset"] = { "Load this read-only preset. Save a copy with Create as new to keep your edits.", "Lädt diese schreibgeschützte Vorlage. Änderungen mit „Als neu speichern“ als eigenes Profil speichern." },
    ["Profile own"] = { "Load this shared appearance profile, or this character's retained draft if one exists.", "Lädt dieses gemeinsame Optikprofil oder den vorhandenen lokalen Entwurf dieses Charakters." },
    ["Profile custom"] = { "Return to this character's custom appearance and retained draft.", "Kehrt zur eigenen Optik und zum gespeicherten Entwurf dieses Charakters zurück." },
    ["Context assignment"] = { "Assign this profile to the current context field. It may load now if that context is active.", "Weist dieses Profil dem Kontext dieses Feldes zu. Ist er aktuell aktiv, kann das Profil sofort laden." },
    ["Keep current profile"] = { "Do not switch profiles when entering this context.", "Beim Wechsel in diesen Kontext das aktuelle Profil beibehalten." },
    ["Move window"] = { "Drag the title bar to move the window. Its position is saved; Escape closes it.", "Titelleiste ziehen, um das Fenster zu verschieben. Position wird gespeichert; Escape schließt es." },
    ["Close window"] = { "Close settings and stop preview ticks and frame picking. Applied settings remain saved.", "Schließt Einstellungen und beendet Vorschau-Ticks und Frame-Auswahl. Übernommene Einstellungen bleiben gespeichert." },
    ["Display to edit"] = { "Switch the edited display and preview. Does not enable or disable either display.", "Wechselt bearbeitete Anzeige und Vorschau. Aktiviert oder deaktiviert keine Anzeige." },
    ["Select appearance profile"] = { "Load a profile for both displays. * marks local edits. Manage shared profiles under Profiles.", "Lädt ein Profil für beide Anzeigen. * markiert lokale Änderungen. Gemeinsame Profile unter „Profile“ verwalten." },
    ["Reset appearance"] = { "Reset this display's appearance; linked fields affect both. Keep general switches, anchor paths, profiles and learning.", "Setzt die Optik dieser Anzeige zurück; gekoppelte Felder wirken auf beide. Allgemeine Schalter, Ankerpfade, Profile und Lernwerte bleiben." },
    ["Reset advanced"] = { "Restore None and, for the target, automatic health-bar detection. Keep learned damage and profiles.", "Stellt „Keine“ und die automatische Lebensbalken-Erkennung im Zielfenster wieder her. Lernwerte und Profile bleiben." },
    ["Survives"] = { "Preview 60% HP and 45% remaining DoT damage. Stop simulated ticks; no combat data changes.", "Vorschau mit 60 % HP und 45 % DoT-Restschaden. Stoppt Vorschau-Ticks; ändert keine Kampfdaten." },
    ["Lethal"] = { "Preview 60% HP and 72% remaining DoT damage to test the kill icon. Stop simulated ticks.", "Vorschau mit 60 % HP und 72 % DoT-Restschaden zum Testen des Kill-Symbols. Stoppt Vorschau-Ticks." },
    ["Health"] = { "Preview enemy HP as a percentage of maximum HP. Changes only the example and stops simulated ticks.", "Gegner-HP der Vorschau in Prozent der maximalen HP. Ändert nur das Beispiel und stoppt Vorschau-Ticks." },
    ["DoT damage"] = { "Preview remaining DoT damage as a percentage of maximum HP. Changes only the example and stops simulated ticks.", "DoT-Restschaden der Vorschau in Prozent der maximalen HP. Ändert nur das Beispiel und stoppt Vorschau-Ticks." },
    ["Play ticks"] = { "Simulate up to six ticks, one every 0.5 seconds. HP and remaining damage decrease together; click again to pause.", "Simuliert bis zu sechs Ticks im Abstand von 0,5 Sekunden. HP und Restschaden sinken gemeinsam; erneut klicken pausiert." },
    ["Open DoTDamage"] = { "Open the settings editor and damage forecast preview.", "Öffnet Einstellungen und Schadensvorschau." },
    ["DoTDamage"] = { "Click to open settings and the preview. You can also use /dot.", "Klicken öffnet Einstellungen und Vorschau. Alternativ /dot verwenden." },
    ["Number input"] = { "Enter or leaving applies; Escape cancels. Decimal point or comma accepted.", "Enter oder Verlassen übernimmt, Escape verwirft. Dezimalpunkt und Komma sind erlaubt." },
    ["Colour option"] = { "Use this colour for the selected field.", "Verwendet diese Farbe für das gewählte Feld." },
    ["option:auto"] = { "Use the DoT's default colour.", "Verwendet die Standardfarbe dieses DoTs." },
    ["option:custom"] = { "Open WoW's colour picker for a custom RGB colour.", "Öffnet den WoW-Farbwähler für eine eigene RGB-Farbe." },
    ["option:Fill texture:none"] = { "Hide the fill. Keep enabled outline, kill icon and damage text.", "Blendet die Füllung aus. Aktivierte Kontur, Kill-Symbol und Schadenstext bleiben." },
    ["option:Fill texture:flat"] = { "Uniform solid fill without a texture pattern.", "Gleichmäßige Füllung ohne Texturmuster." },
    ["option:Fill texture:smooth"] = { "Use Blizzard's standard health-bar texture.", "Verwendet Blizzards Standard-Lebensbalkentextur." },
    ["option:Fill texture:raid"] = { "Use Blizzard's raid health-bar texture.", "Verwendet Blizzards Raid-Lebensbalkentextur." },
    ["option:Fill texture:stripes"] = { "Use the original 0.6 stripe pattern with its stepped diagonal lines.", "Verwendet das ursprüngliche 0.6-Streifenmuster mit abgestuften diagonalen Linien." },
    ["option:Fill texture:stripes05"] = { "Use the classic diagonal stripe pattern from 0.5.", "Verwendet das klassische diagonale Streifenmuster aus 0.5." },
    ["option:Fill texture:gradient"] = { "Fade from transparent on the left to the chosen fill opacity on the right.", "Verlauf von transparent links bis zur gewählten Fülldeckkraft rechts." },
    ["option:Color mode:single"] = { "Use Fill tint for the entire forecast.", "Verwendet die Füllfarbe für die gesamte Prognose." },
    ["option:Color mode:school"] = { "Colour segments by their spell's damage school.", "Färbt Abschnitte nach der Schadensschule ihres Zaubers." },
    ["option:Color mode:each"] = { "Give each DoT its own colour; adjust them under DoT colors.", "Gibt jedem DoT eine eigene Farbe; unter „DoT-Farben“ anpassbar." },
    ["option:Outline:none"] = { "Hide the outline and its glow.", "Blendet Kontur und ihr Leuchten aus." },
    ["option:Outline:solid"] = { "Draw a continuous border around the forecast.", "Zeichnet eine durchgehende Kontur um die Prognose." },
    ["option:Outline:dashed"] = { "Draw a border using the selected Dash pattern.", "Zeichnet eine Kontur mit dem gewählten „Strichmuster“." },
    ["option:Extra tick wait:off"] = { "Show as soon as tracking permits, using learned damage or the tooltip. Required aura/impact checks still apply.", "Zeigt an, sobald Tracking es erlaubt, mit Lernwerten oder Tooltip-Schaden. Nötige Aura-/Trefferprüfungen bleiben aktiv." },
    ["option:Extra tick wait:unsure"] = { "Wait for the first tick while no usable learned value exists. Required aura/impact checks still apply.", "Wartet auf den ersten Tick, solange kein nutzbarer Lernwert vorliegt. Nötige Aura-/Trefferprüfungen bleiben aktiv." },
    ["option:Extra tick wait:always"] = { "Wait for the first tick of each application, even with learned damage.", "Wartet bei jeder Anwendung auf den ersten Tick, auch bei gelerntem Schaden." },
    ["option:Position:left"] = { "Put the icon left of the nameplate health bar; then apply its offsets.", "Platziert das Symbol links neben dem Lebensbalken der Namensplakette; anschließend gelten die Abstände." },
    ["option:Position:right"] = { "Put the icon right of the nameplate health bar; then apply its offsets.", "Platziert das Symbol rechts neben dem Lebensbalken der Namensplakette; anschließend gelten die Abstände." },
    ["option:Position:above"] = { "Centre the icon above the nameplate health bar; then apply its offsets.", "Platziert das Symbol mittig über dem Lebensbalken der Namensplakette; anschließend gelten die Abstände." },
    ["option:Text position:left"] = { "Show the number outside the bar's left edge.", "Zeigt die Zahl außerhalb des linken Balkenrands." },
    ["option:Text position:center"] = { "Centre the number on the bar.", "Zeigt die Zahl mittig auf dem Balken." },
    ["option:Text position:right"] = { "Show the number inside the bar at its right edge.", "Zeigt die Zahl rechts innerhalb des Balkens." },
    ["option:Icon design:skull"] = { "Use the raid-target skull symbol as the kill icon.", "Verwendet den Totenkopf der Raid-Zielmarkierungen als Kill-Symbol." },
    ["option:Icon design:cross"] = { "Use a colourable X as the kill icon.", "Verwendet ein frei einfärbbares X als Kill-Symbol." },
    ["option:Icon design:check"] = { "Use the green ready-check checkmark as the kill icon.", "Verwendet den grünen Bereitschaftscheck-Haken als Kill-Symbol." },
    ["option:Icon design:diamond"] = { "Use a colourable diamond as the kill icon.", "Verwendet eine frei einfärbbare Raute als Kill-Symbol." },
    ["section:General"] = { "Tracking, display switches and shared appearance options. Click to expand or collapse.", "Tracking, Anzeigeschalter und gekoppelte Optik. Klicken klappt die Gruppe auf oder zu." },
    ["section:Damage bar"] = { "Fill, colour and outline of this display. Click to expand or collapse.", "Füllung, Farbe und Kontur dieser Anzeige. Klicken klappt die Gruppe auf oder zu." },
    ["section:DoT colors"] = { "Colours for individual DoTs in Different color per DoT mode. Click to expand or collapse.", "Einzelfarben für den Modus „Eigene Farbe je DoT“. Klicken klappt die Gruppe auf oder zu." },
    ["section:Kill icon"] = { "Symbol, size and placement of the estimated-kill indicator. Click to expand or collapse.", "Symbol, Größe und Position der geschätzten Kill-Anzeige. Klicken klappt die Gruppe auf oder zu." },
    ["section:Bar effects"] = { "Target-frame visual effects and their preview. Click to expand or collapse.", "Optische Effekte im Zielfenster und deren Vorschau. Klicken klappt die Gruppe auf oder zu." },
    ["section:Damage text"] = { "Remaining-damage number on the target display. Click to expand or collapse.", "Restschadenszahl an der Zielanzeige. Klicken klappt die Gruppe auf oder zu." },
    ["section:Prediction"] = { "Tracking status and optional first-tick wait. Click to expand or collapse.", "Tracking-Status und zusätzliches Warten auf den ersten Tick. Klicken klappt die Gruppe auf oder zu." },
    ["section:Support"] = { "Save diagnostics or reset this character's learned damage. Click to expand or collapse.", "Diagnose speichern oder Lernwerte dieses Charakters zurücksetzen. Klicken klappt die Gruppe auf oder zu." },
    ["section:UI integration"] = { "Override target health-bar detection if needed. Click to expand or collapse.", "Lebensbalken im Zielfenster bei Bedarf manuell zuweisen. Klicken klappt die Gruppe auf oder zu." },
    ["section:Account-wide appearance profiles"] = { "Load shared profiles and view local editing status. Click to expand or collapse.", "Gemeinsame Profile laden und lokalen Bearbeitungsstand sehen. Klicken klappt die Gruppe auf oder zu." },
    ["section:Save a separate profile"] = { "Create an account-wide profile from the current look. Click to expand or collapse.", "Aus aktueller Optik ein accountweites Profil erstellen. Klicken klappt die Gruppe auf oder zu." },
    ["section:Manage selected profile"] = { "Rename, restore or delete your selected own profile. Click to expand or collapse.", "Gewähltes eigenes Profil umbenennen, wiederherstellen oder löschen. Klicken klappt die Gruppe auf oder zu." },
    ["section:Automatic selection (this character)"] = { "Assign profiles to Solo, Group, Dungeon and Raid for this character. Click to expand or collapse.", "Profile für Solo, Gruppe, Dungeon und Raid dieses Charakters zuweisen. Klicken klappt die Gruppe auf oder zu." },
    ["Appearance"] = { "Edit this display's look, effects and icon placement.", "Optik, Effekte und Icon-Position dieser Anzeige bearbeiten." },
    ["Advanced"] = { "First-tick wait, support reports and manual health-bar detection.", "Tick-Wartezeit, Diagnoseberichte und manuelle Lebensbalken-Erkennung." },
    ["Profiles"] = { "Manage shared appearance profiles and this character's context assignments.", "Gemeinsame Optikprofile und Kontextzuweisungen dieses Charakters verwalten." },
}

local HELP_KEYS = {}
for key, pair in pairs(TEXT) do HELP_KEYS[pair[1]], HELP_KEYS[pair[2]] = key, key end
local translations = type(namespace) == "table" and namespace.UITranslations or {}
for _, language in pairs(translations) do
    for key, body in pairs(language.help) do HELP_KEYS[body] = key end
end
local function translated(key, locale)
    local pair = TEXT[key]
    if not pair then return nil end
    if locale == "deDE" then return pair[2] end
    local code = locale == "esMX" and "esES" or locale
    return translations[code] and translations[code].help[key] or pair[1]
end
function Tooltips.localize(body, locale)
    return translated(HELP_KEYS[body], locale) or body
end

function Tooltips.text(key, locale)
    return translated(key, locale)
end

if type(namespace) == "table" then namespace.UITooltips = Tooltips end
return Tooltips
